module Prob_5_58 (output reg y_out, input x_in, clk, reset_b);
  parameter s0 = 2'b00;  parameter s1 = 2'b01;  parameter s2 = 2'b10;  parameter s3 = 2'b11;  reg [1:0] state, next_state;  always @ (posedge clk, negedge reset_b)    if (reset_b == 1'b0) state <= s0;    else state <= next_state;  always @(state, x_in) begin    y_out = 0;    next_state = s0;    case(state)      s0:	if (x_in == 1'b0) next_state = s0; else if (x_in == 1'b1) next_state = s1;      s1:	if (x_in == 1'b0) next_state = s0; else if (x_in == 1'b1) next_state = s2;      s2:	if (x_in == 1'b0) next_state = s0; else if (x_in == 1'b1) next_state = s3;      s3:	begin y_out = 1; if (x_in == 1'b0) next_state = s0; else if (x_in == 1'b1) next_state = s3; end;      default:	begin next_state = s0; y_out = 0; end;    endcase  end
 endmodule